sys_script_client.script:
function onLoad() {
	// Joe employee has the usernmae value to 'employee'
	if(g_user.userName === 'employee' || /joe employee/gi.test(g_user.getFullName())) {
		g_form.clearMessages();
		ScriptLoader.getScripts('CustomUtils.jsdbx', function() {
		console.log('Yo papa', CustomUtils);

		var messageName = 'custom_you_cannot_add_incident';

		CustomUtils.i18nTranslate(
				messageName, 
				function(translations) {
					g_form.addFormMessage(translations[messageName], 'error');
				});
		});

	}
}
